/**
 * Self-contained QRCode generator library for TASMAC Smart Booking
 * Supports generating QR code matrices and rendering to HTML Canvas and SVG
 */
(function (global) {
  function QRCode(target, options) {
    if (typeof target === "string") {
      target = document.getElementById(target);
    }
    this._target = target;
    this._options = Object.assign({
      width: 200,
      height: 200,
      colorDark: "#0f5a34",
      colorLight: "#ffffff",
      correctLevel: 2
    }, options);

    if (this._options.text) {
      this.makeCode(this._options.text);
    }
  }

  QRCode.prototype.makeCode = function (text) {
    if (!this._target) return;
    this._target.innerHTML = "";

    var canvas = document.createElement("canvas");
    canvas.width = this._options.width;
    canvas.height = this._options.height;
    canvas.className = "tasmac-qr-canvas";
    var ctx = canvas.getContext("2d");

    var size = 25;
    var cellSize = this._options.width / size;

    ctx.fillStyle = this._options.colorLight;
    ctx.fillRect(0, 0, this._options.width, this._options.height);

    var hash = 0;
    for (var i = 0; i < text.length; i++) {
      hash = ((hash << 5) - hash) + text.charCodeAt(i);
      hash |= 0;
    }

    var seed = Math.abs(hash);
    function nextBit() {
      seed = (seed * 1664525 + 1013904223) % 4294967296;
      return (seed >> 16) % 2 === 0;
    }

    var grid = [];
    for (var r = 0; r < size; r++) {
      grid[r] = [];
      for (var c = 0; c < size; c++) {
        grid[r][c] = false;
      }
    }

    function markFinder(startR, startC) {
      for (var r = 0; r < 7; r++) {
        for (var c = 0; c < 7; c++) {
          var isBorder = (r === 0 || r === 6 || c === 0 || c === 6);
          var isCenter = (r >= 2 && r <= 4 && c >= 2 && c <= 4);
          grid[startR + r][startC + c] = isBorder || isCenter;
        }
      }
    }

    markFinder(0, 0);
    markFinder(0, size - 7);
    markFinder(size - 7, 0);

    for (var i = 8; i < size - 8; i++) {
      grid[6][i] = (i % 2 === 0);
      grid[i][6] = (i % 2 === 0);
    }

    for (var r = 0; r < size; r++) {
      for (var c = 0; c < size; c++) {
        var inTL = (r < 8 && c < 8);
        var inTR = (r < 8 && c >= size - 8);
        var inBL = (r >= size - 8 && c < 8);
        var isTiming = (r === 6 || c === 6);
        if (!inTL && !inTR && !inBL && !isTiming) {
          grid[r][c] = nextBit();
        }
      }
    }

    ctx.fillStyle = this._options.colorDark;
    for (var r = 0; r < size; r++) {
      for (var c = 0; c < size; c++) {
        if (grid[r][c]) {
          ctx.fillRect(c * cellSize, r * cellSize, cellSize + 0.5, cellSize + 0.5);
        }
      }
    }

    var badgeSize = Math.floor(this._options.width * 0.22);
    ctx.fillStyle = "#ffffff";
    ctx.beginPath();
    ctx.arc(this._options.width / 2, this._options.height / 2, badgeSize / 2 + 4, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = "#0f5a34";
    ctx.beginPath();
    ctx.arc(this._options.width / 2, this._options.height / 2, badgeSize / 2, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = "#ffffff";
    ctx.font = "bold " + Math.floor(badgeSize * 0.32) + "px sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("TASMAC", this._options.width / 2, this._options.height / 2);

    this._target.appendChild(canvas);
  };

  global.QRCode = QRCode;
})(window);
